[{"order":1,"type":"heading","text":"Middleware Architecture, Edge Runtime, and Use Cases in Next.js"},{"order":2,"type":"subheading","text":"Introduction to Next.js Middleware"},{"order":3,"type":"paragraph","text":"Next.js Middleware allows you to run code before a request is completed. Based on the incoming request, you can modify the response by rewriting, redirecting, modifying request or response headers, or responding directly. Middleware executes before any content is rendered on the server or cached, making it ideal for global tasks such as authentication and routing."},{"order":4,"type":"subheading","text":"Understanding the Edge Runtime"},{"order":5,"type":"paragraph","text":"Unlike the Node.js runtime, Next.js Middleware runs on the Edge Runtime. The Edge Runtime is a lightweight execution environment built on top of the V8 JavaScript engine. It is designed to run close to the user via Content Delivery Networks (CDNs), reducing latency. However, because it relies on standard Web APIs (like Fetch, Request, and Response), it does not support all Node.js native modules (such as fs or path)."},{"order":6,"type":"subheading","text":"Setting Up Middleware"},{"order":7,"type":"paragraph","text":"To implement middleware in your Next.js application, create a file named middleware.ts (or middleware.js) at the root of your project directory (at the same level as app or pages, or inside src if you use the src directory)."},{"order":8,"type":"code","text":"import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  return NextResponse.next();
}

export const config = {
  matcher: '/about/:path*',
};"},{"order":9,"type":"subheading","text":"Use Case 1: Authentication and Authorization"},{"order":10,"type":"paragraph","text":"Authentication is one of the most common use cases for middleware. You can intercept requests to protected routes, verify session tokens or cookies, and redirect unauthorized users to the login page before any resource-intensive page rendering occurs."},{"order":11,"type":"code","text":"import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  const token = request.cookies.get('token')?.value;

  if (!token) {
    const loginUrl = new URL('/login', request.url);
    return NextResponse.redirect(loginUrl);
  }

  return NextResponse.next();
}

export const config = {
  matcher: '/dashboard/:path*',
};"},{"order":12,"type":"subheading","text":"Use Case 2: Advanced Routing and Internationalization"},{"order":13,"type":"paragraph","text":"Middleware enables dynamic routing logic, such as geo-based redirection, A/B testing splits, and internationalization (i18n). You can inspect incoming headers like accept-language or user-agent to rewrite requests to localized paths seamlessly."},{"order":14,"type":"code","text":"import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  const country = request.geo?.country || 'US';

  if (country === 'FR') {
    return NextResponse.rewrite(new URL('/fr', request.url));
  }

  return NextResponse.next();
}"},{"order":15,"type":"subheading","text":"Best Practices for Edge Middleware"},{"order":16,"type":"bullet_point","text":"Keep middleware execution lightweight to maintain fast response times at the edge."},{"order":17,"type":"bullet_point","text":"Use the matcher config property wisely to avoid running middleware on static assets and API routes unnecessarily."},{"order":18,"type":"bullet_point","text":"Remember that the Edge Runtime lacks Node.js APIs; use Web standard libraries (like crypto or jose for JWT verification)."}]
